func recordEntry(path, kind string, values map[string]any) template.ScaffoldEntry {
	return template.ScaffoldEntry{
		Path: path,
		Scaffold: template.Scaffold{
			Template:  kind,
			Version:   "v1.0.0",
			Values:    values,
			BlockKind: kind,
		},
	}
