			t.Fatalf("topic keys = %+v", facts.TopicKeys)
		}
	})

	t.Run("missing root yields empty facts without error", func(t *testing.T) {
		facts, warnings := LoadWorkspaceFacts(filepath.Join(t.TempDir(), "nope"))
		if len(warnings) > 1 {
			t.Fatalf("warnings = %v", warnings)
		}
		if len(facts.TopicKeys) != 0 {
			t.Fatalf("topic keys = %+v", facts.TopicKeys)
		}
	})
}

package template

import (
	"sort"
)

// TopicKey identifies a pub/sub topic within a workspace: the pub/sub
// component it lives on plus the topic name. It is the key workspace facts
// dedupe on — two scaffold records naming the same key declare the two
// halves of one contract.
type TopicKey struct {
	Pubsub string
	Topic  string
}

// WorkspaceFacts is the prompt-time view of what a workspace's scaffold
// records already declare: the topics in use, the contract each carries,
// and the external ports already named. Create flows derive parameter
// suggestions from it; it is built by callers that scan workspaces
// (internal/system) and consumed read-only by value resolution.
//
// BuildWorkspaceFacts constructs one from scaffold entries; the zero value
// is a valid empty index.
type WorkspaceFacts struct {
	// TopicKeys holds the distinct topic keys in use, sorted by
	// (Pubsub, Topic).
	TopicKeys []TopicKey

	// Ports holds the distinct external port names in use, sorted
	// lexicographically.
	Ports []string

	// contracts maps a topic key to its recorded contract type. A key whose
	// records disagree on the contract is absent — a conflicted fact is no
	// fact, and callers treat absence as "no suggestion".
	contracts map[TopicKey]string
}

// ContractFor returns the contract type recorded for a topic key, or
// ("", false) when the key is unknown or its records conflict.
func (f *WorkspaceFacts) ContractFor(key TopicKey) (string, bool) {
	if f == nil {
		return "", false
	}
	c, ok := f.contracts[key]
	return c, ok
}

// WorkspaceFactEntry is the slice of a scaffold record fact-building reads:
// which block the record scaffolds and the values it recorded. Keeping the
// input this narrow lets BuildWorkspaceFacts stay in this package — a
// caller-side adapter maps full scaffold records to entries, and the import
// graph never cycles back through the scanner.
type WorkspaceFactEntry struct {
	// BlockKind is the record's block kind ("extractor", "loader",
	// "transactional-integration"); entries with any other kind contribute
	// nothing.
	BlockKind string

	// Values is the record's resolved parameter values.
	Values map[string]any
}

// BuildWorkspaceFacts indexes entries into workspace facts. It is
// deliberately lenient where Assemble is strict: entries with missing or
// mistyped wiring values are skipped rather than reported, because a
// suggestion aid must never fail an operation the records themselves would
// still allow. The one cross-record rule it shares with Assemble is that
// conflicting contracts on one topic key demote the contract — suggesting
// either side of a conflict would bake a guess into the new record.
func BuildWorkspaceFacts(entries []WorkspaceFactEntry) *WorkspaceFacts {
	facts := &WorkspaceFacts{contracts: map[TopicKey]string{}}
	type contractSighting struct {
		contract   string
		conflicted bool
	}
	sightings := map[TopicKey]*contractSighting{}
	seenTopic := map[TopicKey]bool{}
	seenPort := map[string]bool{}

	for _, e := range entries {
		switch e.BlockKind {
		case BlockKindExtractor, BlockKindLoader:
			topic, tok := stringValue(e.Values, "topic")
			contract, cok := stringValue(e.Values, "contract")
			pubsub, _ := stringValue(e.Values, "pubsub")
			if pubsub == "" {
				pubsub = "pubsub"
			}
			if tok && cok {
				key := TopicKey{Pubsub: pubsub, Topic: topic}
				if !seenTopic[key] {
					seenTopic[key] = true
					facts.TopicKeys = append(facts.TopicKeys, key)
				}
				if s, seen := sightings[key]; seen {
					if s.contract != contract {
						s.conflicted = true
					}
				} else {
					sightings[key] = &contractSighting{contract: contract}
				}
			}
			if port, ok := stringValue(e.Values, "port"); ok && !seenPort[port] {
				seenPort[port] = true
				facts.Ports = append(facts.Ports, port)
			}
		case BlockKindTransactional:
			for _, name := range []string{"fromPort", "toPort"} {
				if port, ok := stringValue(e.Values, name); ok && !seenPort[port] {
					seenPort[port] = true
					facts.Ports = append(facts.Ports, port)
				}
			}
		}
	}

	for key, s := range sightings {
		if !s.conflicted {
			facts.contracts[key] = s.contract
		}
	}
	sort.Slice(facts.TopicKeys, func(i, j int) bool {
		if facts.TopicKeys[i].Pubsub != facts.TopicKeys[j].Pubsub {
			return facts.TopicKeys[i].Pubsub < facts.TopicKeys[j].Pubsub
		}
		return facts.TopicKeys[i].Topic < facts.TopicKeys[j].Topic
	})
	sort.Strings(facts.Ports)
	return facts
}

// stringValue reads values[key] as a non-empty string, reporting false for
// missing, mistyped, or empty values. Fact-building skips such entries
// rather than failing — the records may predate the value.
func stringValue(values map[string]any, key string) (string, bool) {
	s, ok := values[key].(string)
	if !ok || s == "" {
		return "", false
	}
	return s, true
}

package system

import (
	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// LoadWorkspaceFacts scans root for scaffold records and indexes what they
// declare into prompt-time workspace facts. Warnings are non-fatal: one
// malformed record must not hide the facts the rest of the workspace
// carries, and a suggestion aid never aborts the create it assists. A
// missing or record-free root yields an empty index.
func LoadWorkspaceFacts(root string) (*template.WorkspaceFacts, []error) {
	entries, warnings := template.ListScaffolds(root)
	return WorkspaceFactsOf(entries), warnings
}

// WorkspaceFactsOf adapts scanned scaffold records into the fact index,
// dropping records that carry no block wiring (shared libraries, system
// hosts) before indexing.
func WorkspaceFactsOf(entries []template.ScaffoldEntry) *template.WorkspaceFacts {
	factEntries := make([]template.WorkspaceFactEntry, 0, len(entries))
	for _, e := range entries {
		if e.BlockKind == "" {
			continue
		}
		factEntries = append(factEntries, template.WorkspaceFactEntry{
			BlockKind: e.BlockKind,
			Values:    e.Values,
		})
	}
	return template.BuildWorkspaceFacts(factEntries)
}

package template

import (
	"testing"
)

func factEntry(kind string, values map[string]any) WorkspaceFactEntry {
	return WorkspaceFactEntry{BlockKind: kind, Values: values}
}

func TestBuildWorkspaceFacts(t *testing.T) {
	t.Run("extractor and loader sharing a topic contribute one key, one contract, both ports", func(t *testing.T) {
		entries := []WorkspaceFactEntry{
			factEntry(BlockKindExtractor, map[string]any{
				"appId": "order-extractor", "topic": "orders", "contract": "Order", "pubsub": "pubsub", "port": "erp",
			}),
			factEntry(BlockKindLoader, map[string]any{
				"appId": "audit-loader", "topic": "orders", "contract": "Order", "pubsub": "pubsub", "port": "warehouse",
			}),
		}
		facts := BuildWorkspaceFacts(entries)
		if len(facts.TopicKeys) != 1 || facts.TopicKeys[0] != (TopicKey{Pubsub: "pubsub", Topic: "orders"}) {
			t.Fatalf("topic keys = %+v", facts.TopicKeys)
		}
		if got, ok := facts.ContractFor(TopicKey{Pubsub: "pubsub", Topic: "orders"}); !ok || got != "Order" {
			t.Fatalf("contract = %q, %v", got, ok)
		}
		if len(facts.Ports) != 2 || facts.Ports[0] != "erp" || facts.Ports[1] != "warehouse" {
			t.Fatalf("ports = %+v", facts.Ports)
		}
	})

	t.Run("transactional record contributes both ports and no topic", func(t *testing.T) {
		entries := []WorkspaceFactEntry{
			factEntry(BlockKindTransactional, map[string]any{
				"appId": "sync", "fromPort": "crm", "toPort": "erp",
			}),
		}
		facts := BuildWorkspaceFacts(entries)
		if len(facts.TopicKeys) != 0 {
			t.Fatalf("topic keys = %+v", facts.TopicKeys)
		}
		if len(facts.Ports) != 2 || facts.Ports[0] != "crm" || facts.Ports[1] != "erp" {
			t.Fatalf("ports = %+v", facts.Ports)
		}
	})

	t.Run("conflicting contracts on one topic key demote the contract but keep the key", func(t *testing.T) {
		entries := []WorkspaceFactEntry{
			factEntry(BlockKindExtractor, map[string]any{
				"appId": "a", "topic": "orders", "contract": "Order",
			}),
			factEntry(BlockKindLoader, map[string]any{
				"appId": "b", "topic": "orders", "contract": "OrderV2",
			}),
		}
		facts := BuildWorkspaceFacts(entries)
		if len(facts.TopicKeys) != 1 {
			t.Fatalf("topic keys = %+v", facts.TopicKeys)
		}
		if got, ok := facts.ContractFor(facts.TopicKeys[0]); ok || got != "" {
			t.Fatalf("conflicted contract should demote, got %q, %v", got, ok)
		}
	})

	t.Run("records missing wiring values are skipped, others still contribute", func(t *testing.T) {
		entries := []WorkspaceFactEntry{
			factEntry(BlockKindLoader, map[string]any{"appId": "bare"}),
			factEntry(BlockKindExtractor, map[string]any{
				"appId": "partial", "topic": "audits", "contract": "Audit",
			}),
			factEntry(BlockKindLoader, map[string]any{
				"appId": "nonstring", "topic": 7, "contract": "Order",
			}),
		}
		facts := BuildWorkspaceFacts(entries)
		if len(facts.TopicKeys) != 1 || facts.TopicKeys[0].Topic != "audits" {
			t.Fatalf("topic keys = %+v", facts.TopicKeys)
		}
	})

	t.Run("pubsub defaults to pubsub for records that predate the value", func(t *testing.T) {
		entries := []WorkspaceFactEntry{
			factEntry(BlockKindExtractor, map[string]any{
				"appId": "old", "topic": "orders", "contract": "Order",
			}),
		}
		facts := BuildWorkspaceFacts(entries)
		if len(facts.TopicKeys) != 1 || facts.TopicKeys[0].Pubsub != "pubsub" {
			t.Fatalf("topic keys = %+v", facts.TopicKeys)
		}
	})

	t.Run("records without a block kind contribute nothing", func(t *testing.T) {
		entries := []WorkspaceFactEntry{
			factEntry("", map[string]any{"name": "Acme.Models"}),
			factEntry("future-kind", map[string]any{"topic": "orders", "contract": "Order"}),
		}
		facts := BuildWorkspaceFacts(entries)
		if len(facts.TopicKeys) != 0 || len(facts.Ports) != 0 {
			t.Fatalf("facts = %+v", facts)
		}
	})

	t.Run("topics sort by pubsub then topic, ports lexicographic", func(t *testing.T) {
		entries := []WorkspaceFactEntry{
			factEntry(BlockKindExtractor, map[string]any{
				"appId": "a", "topic": "orders", "contract": "Order", "pubsub": "z-pubsub", "port": "zeta",
			}),
			factEntry(BlockKindLoader, map[string]any{
				"appId": "b", "topic": "audits", "contract": "Audit", "pubsub": "a-pubsub", "port": "alpha",
			}),
			factEntry(BlockKindLoader, map[string]any{
				"appId": "c", "topic": "billing", "contract": "Invoice", "pubsub": "a-pubsub", "port": "mid",
			}),
		}
		facts := BuildWorkspaceFacts(entries)
		wantTopics := []TopicKey{
			{Pubsub: "a-pubsub", Topic: "audits"},
			{Pubsub: "a-pubsub", Topic: "billing"},
			{Pubsub: "z-pubsub", Topic: "orders"},
		}
		if len(facts.TopicKeys) != 3 {
			t.Fatalf("topic keys = %+v", facts.TopicKeys)
		}
		for i, want := range wantTopics {
			if facts.TopicKeys[i] != want {
				t.Fatalf("topic keys[%d] = %+v, want %+v (all: %+v)", i, facts.TopicKeys[i], want, facts.TopicKeys)
			}
		}
		wantPorts := []string{"alpha", "mid", "zeta"}
		for i, want := range wantPorts {
			if facts.Ports[i] != want {
				t.Fatalf("ports = %+v, want %v", facts.Ports, wantPorts)
			}
		}
	})

	t.Run("empty input yields an empty index", func(t *testing.T) {
		facts := BuildWorkspaceFacts(nil)
		if facts == nil || len(facts.TopicKeys) != 0 || len(facts.Ports) != 0 {
			t.Fatalf("facts = %+v", facts)
		}
		if _, ok := facts.ContractFor(TopicKey{Pubsub: "p", Topic: "t"}); ok {
			t.Fatal("empty index should have no contracts")
		}
	})
}

package system

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

func TestWorkspaceFactsOf(t *testing.T) {
	t.Run("block records contribute, role records do not", func(t *testing.T) {
		block := template.ScaffoldEntry{
			Path: "order-extractor",
			Scaffold: template.Scaffold{
				Values:    map[string]any{"appId": "order-extractor", "topic": "orders", "contract": "Order"},
				BlockKind: template.BlockKindExtractor,
			},
		}
		lib := template.ScaffoldEntry{
			Path:     "Acme.Models",
			Scaffold: template.Scaffold{Values: map[string]any{"name": "Acme.Models"}, Role: template.RoleSharedLibrary},
		}
		facts := WorkspaceFactsOf([]template.ScaffoldEntry{block, lib})
		if len(facts.TopicKeys) != 1 || facts.TopicKeys[0].Topic != "orders" {
			t.Fatalf("topic keys = %+v", facts.TopicKeys)
		}
	})
}

func TestLoadWorkspaceFacts(t *testing.T) {
	writeRecord := func(t *testing.T, dir string, s template.Scaffold) {
		t.Helper()
		if err := template.WriteScaffold(dir, s); err != nil {
			t.Fatal(err)
		}
	}

	t.Run("collects facts from records under root", func(t *testing.T) {
		root := t.TempDir()
		writeRecord(t, filepath.Join(root, "order-extractor"), template.Scaffold{
			SchemaVersion: template.ScaffoldSchemaVersion,
			Template:      "extractor",
			Version:       "v1.0.0",
			Values:        map[string]any{"appId": "order-extractor", "topic": "orders", "contract": "Order"},
			BlockKind:     template.BlockKindExtractor,
		})
		facts, warnings := LoadWorkspaceFacts(root)
		if len(warnings) != 0 {
			t.Fatalf("warnings = %v", warnings)
		}
		if len(facts.TopicKeys) != 1 || facts.TopicKeys[0].Topic != "orders" {
			t.Fatalf("topic keys = %+v", facts.TopicKeys)
		}
	})

	t.Run("a malformed record warns without hiding the rest", func(t *testing.T) {
		root := t.TempDir()
		bad := filepath.Join(root, "bad", ".intropy")
		if err := os.MkdirAll(bad, 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(bad, "scaffold.json"), []byte("{nope"), 0o644); err != nil {
			t.Fatal(err)
		}
		writeRecord(t, filepath.Join(root, "good"), template.Scaffold{
			SchemaVersion: template.ScaffoldSchemaVersion,
			Template:      "loader",
			Version:       "v1.0.0",
			Values:        map[string]any{"appId": "good", "topic": "audits", "contract": "Audit"},
			BlockKind:     template.BlockKindLoader,
		})
		facts, warnings := LoadWorkspaceFacts(root)
		if len(warnings) == 0 || !strings.Contains(warnings[0].Error(), "bad") {
			t.Fatalf("warnings = %v", warnings)
		}
		if len(facts.TopicKeys) != 1 || facts.TopicKeys[0].Topic != "audits" {
			t.Fatalf("topic keys = %+v", facts.TopicKeys)
		}
	})

	t.Run("missing root yields empty facts without fatal warnings", func(t *testing.T) {
		facts, _ := LoadWorkspaceFacts(filepath.Join(t.TempDir(), "nope"))
		if len(facts.TopicKeys) != 0 {
			t.Fatalf("topic keys = %+v", facts.TopicKeys)
		}
	})
}

package template

// Suggest computes prompt-time candidate values for a template's declared
// fields from workspace facts and the values confirmed so far this run.
// The result is keyed by parameter name; fields the convention registry
// does not know, and fields with no candidates, are absent.
//
// The registry is CLI-owned convention, not manifest schema: it mirrors
// the value names the block templates record (topic, pubsub, contract,
// port, fromPort, toPort — the same names internal/system's block parsers
// assemble from). A template whose parameters use other names simply gets
// no suggestions.
//
// Suggestions are prompt metadata only. They never enter the values map on
// their own: a candidate becomes a value only when the prompter confirms
// it with the user, and callers record the confirmed value under the
// field's name — never the candidate list.
func Suggest(fields []FieldSpec, facts *WorkspaceFacts, confirmed map[string]any) map[string][]string {
	if facts == nil {
		return nil
	}
	out := map[string][]string{}
	for _, f := range fields {
		candidates := suggestField(f, facts, confirmed)
		candidates = dropDefaultCandidate(candidates, f)
		if len(candidates) > 0 {
			out[f.Name] = candidates
		}
	}
	return out
}

// suggestField is the convention registry: parameter name -> candidates
// derivable from the facts and the values confirmed so far. Chained
// derivation (contract follows the confirmed topic) re-reads the confirmed
// values on every call rather than threading field-to-field wiring, so the
// registry stays a flat name-to-rule table.
func suggestField(f FieldSpec, facts *WorkspaceFacts, confirmed map[string]any) []string {
	switch f.Name {
	case "topic":
		topics := make([]string, 0, len(facts.TopicKeys))
		for _, key := range facts.TopicKeys {
			topics = append(topics, key.Topic)
		}
		return topics
	case "pubsub":
		seen := map[string]bool{}
		var pubs []string
		for _, key := range facts.TopicKeys {
			if !seen[key.Pubsub] {
				seen[key.Pubsub] = true
				pubs = append(pubs, key.Pubsub)
			}
		}
		return pubs
	case "contract":
		// With a confirmed topic, the contract is constrained to it; a
		// conflicted or unknown key yields nothing rather than a guess.
		// Without one, every known contract is a candidate.
		if topic, ok := confirmedString(confirmed, "topic"); ok {
			pubsub, _ := confirmedString(confirmed, "pubsub")
			if pubsub == "" {
				pubsub = "pubsub"
			}
			if contract, ok := facts.ContractFor(TopicKey{Pubsub: pubsub, Topic: topic}); ok {
				return []string{contract}
			}
			return nil
		}
		return knownContracts(facts)
	case "port", "fromPort", "toPort":
		return facts.Ports
	}
	return nil
}

// knownContracts lists every unconflicted contract the facts carry, in
// topic-key order with duplicates removed.
func knownContracts(facts *WorkspaceFacts) []string {
	seen := map[string]bool{}
	var out []string
	for _, key := range facts.TopicKeys {
		contract, ok := facts.ContractFor(key)
		if ok && !seen[contract] {
			seen[contract] = true
			out = append(out, contract)
		}
	}
	return out
}

// dropDefaultCandidate removes candidates the field's schema default
// already communicates — the prompt's default bracket and a suggestion
// list must never compete for the same value.
func dropDefaultCandidate(candidates []string, f FieldSpec) []string {
	def, ok := f.Default.(string)
	if !ok || def == "" {
		return candidates
	}
	out := candidates[:0]
	for _, c := range candidates {
		if c != def {
			out = append(out, c)
		}
	}
	return out
}

// confirmedString reads a confirmed value as a non-empty string. Confirmed
// values arrive from --set/--values/prompts and are already schema-coerced
// for declared fields; unknown or mistyped entries are treated as absent.
func confirmedString(confirmed map[string]any, key string) (string, bool) {
	s, ok := confirmed[key].(string)
	if !ok || s == "" {
		return "", false
	}
	return s, true
}

