package template

import (
	"reflect"
	"testing"
)

func suggestFacts() *WorkspaceFacts {
	return BuildWorkspaceFacts([]WorkspaceFactEntry{
		{BlockKind: BlockKindExtractor, Values: map[string]any{
			"topic": "orders", "contract": "Order", "pubsub": "pubsub", "port": "erp",
		}},
		{BlockKind: BlockKindLoader, Values: map[string]any{
			"topic": "audits", "contract": "Audit", "pubsub": "pubsub", "port": "warehouse",
		}},
		{BlockKind: BlockKindTransactional, Values: map[string]any{
			"fromPort": "crm", "toPort": "erp",
		}},
	})
}

func suggestField(name string) FieldSpec {
	return FieldSpec{Name: name, Type: "string", Required: true}
}

func TestSuggest(t *testing.T) {
	facts := suggestFacts()

	t.Run("topic and pubsub come from known topic keys, ports from all blocks", func(t *testing.T) {
		fields := []FieldSpec{suggestField("topic"), suggestField("pubsub"), suggestField("port")}
		got := Suggest(fields, facts, nil)
		if !reflect.DeepEqual(got["topic"], []string{"audits", "orders"}) {
			t.Errorf("topic = %v", got["topic"])
		}
		if !reflect.DeepEqual(got["pubsub"], []string{"pubsub"}) {
			t.Errorf("pubsub = %v", got["pubsub"])
		}
		if !reflect.DeepEqual(got["port"], []string{"crm", "erp", "warehouse"}) {
			t.Errorf("port = %v", got["port"])
		}
	})

	t.Run("fromPort and toPort share the port candidates", func(t *testing.T) {
		got := Suggest([]FieldSpec{suggestField("fromPort"), suggestField("toPort")}, facts, nil)
		if !reflect.DeepEqual(got["fromPort"], got["toPort"]) || len(got["fromPort"]) != 3 {
			t.Errorf("fromPort = %v, toPort = %v", got["fromPort"], got["toPort"])
		}
	})

	t.Run("contract chains off a confirmed topic", func(t *testing.T) {
		got := Suggest([]FieldSpec{suggestField("contract")}, facts, map[string]any{"topic": "orders"})
		if !reflect.DeepEqual(got["contract"], []string{"Order"}) {
			t.Errorf("contract = %v", got["contract"])
		}
	})

	t.Run("contract without a confirmed topic lists every known contract", func(t *testing.T) {
		got := Suggest([]FieldSpec{suggestField("contract")}, facts, nil)
		if !reflect.DeepEqual(got["contract"], []string{"Audit", "Order"}) {
			t.Errorf("contract = %v", got["contract"])
		}
	})

	t.Run("confirmed topic unknown to the facts yields no contract suggestion", func(t *testing.T) {
		got := Suggest([]FieldSpec{suggestField("contract")}, facts, map[string]any{"topic": "brand-new"})
		if len(got["contract"]) != 0 {
			t.Errorf("contract = %v", got["contract"])
		}
	})

	t.Run("unregistered parameter names get no suggestions", func(t *testing.T) {
		got := Suggest([]FieldSpec{suggestField("name"), suggestField("appId")}, facts, nil)
		if len(got) != 0 {
			t.Errorf("suggestions = %v", got)
		}
	})

	t.Run("a candidate equal to the schema default is dropped", func(t *testing.T) {
		f := suggestField("pubsub")
		f.Default = "pubsub"
		got := Suggest([]FieldSpec{f}, facts, nil)
		if len(got["pubsub"]) != 0 {
			t.Errorf("pubsub = %v", got["pubsub"])
		}
	})

	t.Run("conflicted contract for the confirmed topic yields nothing", func(t *testing.T) {
		conflicted := BuildWorkspaceFacts([]WorkspaceFactEntry{
			{BlockKind: BlockKindExtractor, Values: map[string]any{"topic": "orders", "contract": "Order"}},
			{BlockKind: BlockKindLoader, Values: map[string]any{"topic": "orders", "contract": "OrderV2"}},
		})
		got := Suggest([]FieldSpec{suggestField("contract")}, conflicted, map[string]any{"topic": "orders"})
		if len(got["contract"]) != 0 {
			t.Errorf("contract = %v", got["contract"])
		}
	})

	t.Run("nil facts yield no suggestions", func(t *testing.T) {
		got := Suggest([]FieldSpec{suggestField("topic")}, nil, nil)
		if got != nil {
			t.Errorf("suggestions = %v", got)
		}
	})
}

func TestResolveInformedChainsAppliedSuggestions(t *testing.T) {
	tmpl := buildTemplate(map[string]any{
		"type":     "object",
		"required": []any{"topic", "contract"},
		"properties": map[string]any{
			"topic":    map[string]any{"type": "string"},
			"contract": map[string]any{"type": "string"},
		},
	}, []string{"topic", "contract"}, nil)
	facts := suggestFacts()

	p := &fakePrompter{
		answers: map[string]any{"topic": "orders", "contract": "Order"},
		applied: map[string][]string{"topic": {"orders"}},
	}
	out, err := ResolveInformed(tmpl, nil, facts, nil, nil, nil, p)
	if err != nil {
		t.Fatal(err)
	}
	if out["topic"] != "orders" || out["contract"] != "Order" {
		t.Fatalf("values = %v", out)
	}
	if len(p.seen) != 2 {
		t.Fatalf("prompts = %d", len(p.seen))
	}
	// The first prompt offers every known topic; the second, chained off
	// the applied topic pick, offers only that topic's contract.
	if !reflect.DeepEqual(p.seen[0].Suggestions, []string{"audits", "orders"}) {
		t.Errorf("topic suggestions = %v", p.seen[0].Suggestions)
	}
	if !reflect.DeepEqual(p.seen[1].Suggestions, []string{"Order"}) {
		t.Errorf("contract suggestions = %v", p.seen[1].Suggestions)
	}
}

func TestResolveInformedMissingErrorNamesKnownValues(t *testing.T) {
	tmpl := buildTemplate(map[string]any{
		"type":     "object",
		"required": []any{"topic"},
		"properties": map[string]any{
			"topic": map[string]any{"type": "string"},
		},
	}, []string{"topic"}, nil)

	_, err := ResolveInformed(tmpl, nil, suggestFacts(), nil, nil, nil, nil)
	if err == nil {
		t.Fatal("expected error")
	}
	want := "missing required parameter(s): topic\nknown topic values in this workspace: audits, orders"
	if err.Error() != want {
		t.Errorf("error = %q, want %q", err.Error(), want)
	}
}

func TestResolveInformedWithoutFactsMatchesResolve(t *testing.T) {
	tmpl := buildTemplate(map[string]any{
		"type":     "object",
		"required": []any{"topic"},
		"properties": map[string]any{
			"topic": map[string]any{"type": "string"},
		},
	}, []string{"topic"}, nil)

	_, err := ResolveInformed(tmpl, nil, nil, nil, nil, nil, nil)
	if err == nil {
		t.Fatal("expected error")
	}
	if err.Error() != "missing required parameter(s): topic" {
		t.Errorf("error = %q", err.Error())
	}
}

package template

import (
	"bytes"
	"strings"
	"testing"
)

func promptRun(t *testing.T, input string, f FieldSpec) (any, []string, string, error) {
	t.Helper()
	var out bytes.Buffer
	p := NewStdinPrompter(strings.NewReader(input), &out)
	v, applied, err := p.Prompt(f)
	return v, applied, out.String(), err
}

func TestStdinPrompterSuggestions(t *testing.T) {
	field := func(suggestions ...string) FieldSpec {
		return FieldSpec{Name: "topic", Type: "string", Required: true, Suggestions: suggestions}
	}

	t.Run("single suggestion: Enter accepts and reports applied", func(t *testing.T) {
		v, applied, out, err := promptRun(t, "\n", field("orders"))
		if err != nil {
			t.Fatal(err)
		}
		if v != "orders" {
			t.Errorf("value = %v", v)
		}
		if len(applied) != 1 || applied[0] != "orders" {
			t.Errorf("applied = %v", applied)
		}
		if !strings.Contains(out, "topic [orders]: ") {
			t.Errorf("output = %q", out)
		}
	})

	t.Run("single suggestion: typing a new value applies nothing", func(t *testing.T) {
		v, applied, _, err := promptRun(t, "brand-new\n", field("orders"))
		if err != nil {
			t.Fatal(err)
		}
		if v != "brand-new" {
			t.Errorf("value = %v", v)
		}
		if len(applied) != 0 {
			t.Errorf("applied = %v", applied)
		}
	})

	t.Run("several suggestions render as a numbered list with a free-text escape", func(t *testing.T) {
		_, _, out, err := promptRun(t, "2\n", field("audits", "orders"))
		if err != nil {
			t.Fatal(err)
		}
		if !strings.Contains(out, "  1) audits\n  2) orders\n") {
			t.Errorf("output = %q", out)
		}
		if !strings.Contains(out, "or type a new value") {
			t.Errorf("output = %q", out)
		}
	})

	t.Run("several suggestions: a numbered pick applies the pick", func(t *testing.T) {
		v, applied, _, err := promptRun(t, "2\n", field("audits", "orders"))
		if err != nil {
			t.Fatal(err)
		}
		if v != "orders" {
			t.Errorf("value = %v", v)
		}
		if len(applied) != 1 || applied[0] != "orders" {
			t.Errorf("applied = %v", applied)
		}
	})

	t.Run("several suggestions: typing the candidate exactly applies it", func(t *testing.T) {
		v, applied, _, err := promptRun(t, "audits\n", field("audits", "orders"))
		if err != nil {
			t.Fatal(err)
		}
		if v != "audits" {
			t.Errorf("value = %v", v)
		}
		if len(applied) != 1 || applied[0] != "audits" {
			t.Errorf("applied = %v", applied)
		}
	})

	t.Run("several suggestions: a novel value is accepted, not rejected", func(t *testing.T) {
		v, applied, _, err := promptRun(t, "brand-new\n", field("audits", "orders"))
		if err != nil {
			t.Fatal(err)
		}
		if v != "brand-new" {
			t.Errorf("value = %v", v)
		}
		if len(applied) != 0 {
			t.Errorf("applied = %v", applied)
		}
	})

	t.Run("several suggestions: empty input re-prompts rather than applying", func(t *testing.T) {
		v, applied, out, err := promptRun(t, "\n1\n", field("audits", "orders"))
		if err != nil {
			t.Fatal(err)
		}
		if v != "audits" {
			t.Errorf("value = %v", v)
		}
		if len(applied) != 1 {
			t.Errorf("applied = %v", applied)
		}
		if !strings.Contains(out, "please choose one") {
			t.Errorf("output = %q", out)
		}
	})

	t.Run("novel value in a list is still pattern-validated", func(t *testing.T) {
		f := field("orders")
		f.Suggestions = []string{"audits", "orders"}
		f.Pattern = `^[a-z]+$`
		v, _, out, err := promptRun(t, "Not Valid\nvalid\n", f)
		if err != nil {
			t.Fatal(err)
		}
		if v != "valid" {
			t.Errorf("value = %v", v)
		}
		if !strings.Contains(out, "value must match") {
