      onSubmit={(e) => {
        e.preventDefault()
        if (canRun) run()
      }}
    >
      <Field
        label="out-dir"
        title="Output directory"
        description="Where the integration is scaffolded, under the workspace root"
        required
      >
        <input
          type="text"
